<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\DcrInitialAccessToken\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Infrastructure\Driver\Rest\DcrInitialAccessTokenAllowController;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Infrastructure\Driver\Rest\DcrInitialAccessTokenListController;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Infrastructure\Driver\Rest\DcrInitialAccessTokenCreateController;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Infrastructure\Driver\Rest\DcrInitialAccessTokenRetrieveController;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Infrastructure\Driver\Rest\DcrInitialAccessTokenUpdateController;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Infrastructure\Driver\Rest\DcrInitialAccessTokenDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Service\Visibility\DcrInitialAccessTokenRestrictFilterToVisibility;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Policy\Filter\TenantAccessible;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Policy\Fields\FixTenantExcludingRoot;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Service\Visibility\DcrInitialAccessTokenCollectNonEditableFields;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Policy\Allow\TenantAdminAllow;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\Create\DcrInitialAccessTokenCreateAllowDecision;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\Update\DcrInitialAccessTokenUpdateAllowDecision;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\List\DcrInitialAccessTokenListAllowDecision;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\Retrieve\DcrInitialAccessTokenRetrieveAllowDecision;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Usecase\Delete\DcrInitialAccessTokenDeleteAllowDecision;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Infrastructure\Driven\DcrInitialAccessTokenQueryRepositoryAdapter;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Infrastructure\Driven\DcrInitialAccessTokenCommandRepositoryAdapter;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\Gateway\DcrInitialAccessTokenQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\Gateway\DcrInitialAccessTokenCommandRepositoryGateway;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Service\Visibility\DcrInitialAccessTokenEnrichForUpdate;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Application\Policy\Formula\TenantFormula;

class DcrInitialAccessTokenPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[DcrInitialAccessTokenQueryRepositoryGateway::class] = \DI\autowire(DcrInitialAccessTokenQueryRepositoryAdapter::class);
        $def[DcrInitialAccessTokenCommandRepositoryGateway::class] = \DI\autowire(DcrInitialAccessTokenCommandRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/access/dcr-initial-access-tokens', [$this, 'setRoutesForDcrInitialAccessToken']);
        $collector->group('/api/me/acl/access/dcr-initial-access-tokens', [$this, 'setRoutesForDcrInitialAccessTokenAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(DcrInitialAccessTokenRestrictFilterToVisibility::class, TenantAccessible::class);
        $listener->registerListener(DcrInitialAccessTokenCollectNonEditableFields::class, FixTenantExcludingRoot::class);
        $listener->registerListener(DcrInitialAccessTokenCreateAllowDecision::class, TenantAdminAllow::class, 'checkCreate');
        $listener->registerListener(DcrInitialAccessTokenUpdateAllowDecision::class, TenantAdminAllow::class, 'checkUpdate');
        $listener->registerListener(DcrInitialAccessTokenListAllowDecision::class, TenantAdminAllow::class, 'checkList');
        $listener->registerListener(DcrInitialAccessTokenRetrieveAllowDecision::class, TenantAdminAllow::class, 'checkRetrieve');
        $listener->registerListener(DcrInitialAccessTokenDeleteAllowDecision::class, TenantAdminAllow::class, 'checkDelete');
        $listener->registerListener(DcrInitialAccessTokenEnrichForUpdate::class, TenantFormula::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("dcr-initial-access-token", "list", "READ");
            $handler->registerResourceAction("dcr-initial-access-token", "create", "WRITE");
            $handler->registerResourceAction("dcr-initial-access-token", "retrieve", "READ");
            $handler->registerResourceAction("dcr-initial-access-token", "update", "WRITE");
            $handler->registerResourceAction("dcr-initial-access-token", "delete", "WRITE");

            $handler->registerResourceAttribute("dcr-initial-access-token", "tenant", "MANAGE");
            $handler->registerResourceAttribute("dcr-initial-access-token", "description", "MANAGE");
            $handler->registerResourceAttribute("dcr-initial-access-token", "tokenHash", "MANAGE");
            $handler->registerResourceAttribute("dcr-initial-access-token", "expiresAt", "MANAGE");
            $handler->registerResourceAttribute("dcr-initial-access-token", "maxUses", "MANAGE");
            $handler->registerResourceAttribute("dcr-initial-access-token", "uses", "MANAGE");
            $handler->registerResourceAttribute("dcr-initial-access-token", "allowedGrantTypes", "MANAGE");
            $handler->registerResourceAttribute("dcr-initial-access-token", "revokedAt", "MANAGE");
            $handler->registerResourceAttribute("dcr-initial-access-token", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForDcrInitialAccessTokenAcl(RouteCollectorProxy $dcrInitialAccessTokenGroup): void
    {
        $dcrInitialAccessTokenGroup->get('', [DcrInitialAccessTokenAllowController::class, 'genericAllow']);
        $dcrInitialAccessTokenGroup->get('/{uid}', [DcrInitialAccessTokenAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForDcrInitialAccessToken(RouteCollectorProxy $dcrInitialAccessTokenGroup): void
    {
        $dcrInitialAccessTokenGroup->get('', [DcrInitialAccessTokenListController::class, 'list']);
        $dcrInitialAccessTokenGroup->post('', [DcrInitialAccessTokenCreateController::class, 'create']);
        $dcrInitialAccessTokenGroup->get('/{uid}', [DcrInitialAccessTokenRetrieveController::class, 'retrieve']);
        $dcrInitialAccessTokenGroup->put('/{uid}', [DcrInitialAccessTokenUpdateController::class, 'update']);
        $dcrInitialAccessTokenGroup->delete('/{uid}', [DcrInitialAccessTokenDeleteController::class, 'delete']);
        $dcrInitialAccessTokenGroup->delete('', [DcrInitialAccessTokenDeleteController::class, 'deleteAllForQuery']);
        $dcrInitialAccessTokenGroup->get('/~/delete-status/{uid}', [DcrInitialAccessTokenDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
